// Persetujuan Tindakan (UX-39, 17:255, 19:89, PR-11, CLIN-022; T-054): one visit. Per active plan: the items and
// doses, the contraindication review of each item (the examining doctor), the text generated by the database to
// read to the patient, the signature pad and "Tanda Tangani" (patient or guardian), and the history (superseded
// and withdrawn versions stay). A plan changed since its consent shows "Perlu persetujuan ulang".
import type { Metadata } from "next";
import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { Suspense } from "react";
import { PageTitle } from "../../../../components/templates/templates";
import { BlockedState, LoadingList, PermissionState } from "../../../../components/ui/states";
import { StatusBadge } from "../../../../components/ui/status-badge";
import { loadPage } from "../data";
import { CaptureForm, ReviewForm, WithdrawForm } from "../forms";
import { CONSENT_STATE, formatDose, HISTORY_STATE, ROLE_LABEL, SIGNER_LABEL, UNIT_LABEL } from "../labels";

export const metadata: Metadata = { title: "Persetujuan Tindakan — Clinic Dashboard" };

const when = (iso: string) => new Intl.DateTimeFormat("id-ID", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Jakarta" }).format(new Date(iso));
const muted = "m-0 text-[0.88rem] text-[var(--label-2)]";
const card = "grid min-w-0 gap-3 rounded-[var(--radius-field)] bg-[var(--surface)] p-4";

async function Body({ params }: { params: Promise<{ visitId: string }> }) {
  const { visitId } = await params;
  const d = await loadPage(visitId);
  if (d.kind === "redirect") redirect(d.to);
  if (d.kind === "forbidden") return <PermissionState object="persetujuan tindakan" />;
  if (d.kind === "not-found") notFound();
  const { visit, patient, examination: exam, plans } = d.page;
  const reviewer = d.isDoctor && exam?.author_id === d.staffId && !visit.closed;
  return (
    <>
      <PageTitle title={patient.name} />
      <p className="m-0 font-semibold">{patient.mrn}{patient.guardian_required ? " · ditandatangani wali" : ""}</p>
      {!exam && <BlockedState reason="Pemeriksaan belum dimulai" unblock="Persetujuan dibuat dari rencana tindakan dokter" />}
      {exam && plans.length === 0 && <p className={muted}>Belum ada rencana tindakan aktif untuk pasien ini.</p>}
      {plans.map((p) => {
        const st = CONSENT_STATE[p.consent];
        const text = d.texts[p.plan_id];
        const active = p.history.find((h) => h.state === "active");
        return (
          <section key={p.plan_id} aria-label={p.title} className="grid min-w-0 gap-4">
            <div className="flex min-w-0 flex-wrap items-center gap-2">
              <h2 className="m-0 text-[1.18rem] font-semibold [overflow-wrap:anywhere]">{p.title}</h2>
              <StatusBadge tone={st.tone}>{st.label}</StatusBadge>
            </div>
            <div className={card}>
              <h3 className="m-0 text-[1.06rem] font-semibold">Item dan dosis</h3>
              {p.items.length === 0 ? <p className={muted}>Rencana belum berisi item.</p> : (
                <ul className="m-0 grid min-w-0 list-none gap-3 p-0">
                  {p.items.map((i) => (
                    <li key={i.plan_item_id} className="grid min-w-0 gap-2 border-t border-[var(--separator)] pt-3">
                      <div className="flex min-w-0 flex-wrap items-center gap-2">
                        <span className="min-w-0 grow basis-[12rem] [overflow-wrap:anywhere]">Tahap {i.stage} · {i.name} × {i.qty}{i.dose_micro != null ? ` · ${formatDose(i.dose_micro)} ${UNIT_LABEL[i.dose_unit!]}` : ""}</span>
                        {i.review === "cleared" && <StatusBadge tone="success">Aman dilakukan</StatusBadge>}
                        {i.review === "blocked" && <StatusBadge tone="danger">Ditahan dokter</StatusBadge>}
                        {!i.review && i.has_contraindications && <StatusBadge tone="warning">Kontraindikasi belum ditinjau</StatusBadge>}
                      </div>
                      {reviewer && (i.has_contraindications || i.review) && exam && (
                        <ReviewForm ctx={d.ctx} visit={visit.id} exam={exam.id} item={i.plan_item_id} name={i.name} />
                      )}
                    </li>
                  ))}
                </ul>
              )}
            </div>
            {text && p.items.length > 0 && (
              <div className={card}>
                <h3 className="m-0 text-[1.06rem] font-semibold">Teks persetujuan</h3>
                <p className={muted}>Bacakan dan jelaskan kepada pasien atau wali sebelum tanda tangan.</p>
                <pre className="m-0 max-h-[24rem] min-w-0 overflow-auto rounded-[var(--radius-field)] bg-white p-3 font-[inherit] text-[0.94rem] whitespace-pre-wrap [overflow-wrap:anywhere]">{text.text}</pre>
                {/* The form stays mounted after signing so its result shows; it then explains that no new consent is needed. */}
                <CaptureForm ctx={d.ctx} visit={visit.id} plan={p.plan_id} hash={text.content_hash} guardianRequired={patient.guardian_required} consented={p.consent === "active"} />
              </div>
            )}
            {visit.closed && <p className={muted}>Kunjungan sudah selesai. Persetujuan tidak dapat diubah.</p>}
            <div className={card}>
              <h3 className="m-0 text-[1.06rem] font-semibold">Riwayat persetujuan</h3>
              {p.history.length === 0 ? <p className={muted}>Belum ada persetujuan.</p> : (
                <ol className="m-0 grid min-w-0 list-none gap-2 p-0" aria-label={`Riwayat persetujuan ${p.title}`}>
                  {p.history.map((h) => (
                    <li key={h.consent_id} className="grid min-w-0 gap-0.5 border-t border-[var(--separator)] pt-2">
                      <span className="font-semibold">Versi {h.version} · {HISTORY_STATE[h.state]}</span>
                      <span className={muted}>
                        {SIGNER_LABEL[h.signer]}{h.guardian_name ? ` (${h.guardian_name})` : ""} · dicatat {ROLE_LABEL[h.captured_as]} {h.captured_by_name ?? ""} · {when(h.captured_at)}
                      </span>
                      {h.withdraw_reason && <span className={muted}>Ditarik: {h.withdraw_reason}</span>}
                    </li>
                  ))}
                </ol>
              )}
              {p.history.length > 0 && !visit.closed && <WithdrawForm ctx={d.ctx} visit={visit.id} consent={active?.consent_id ?? null} />}
            </div>
          </section>
        );
      })}
      <Link href="/persetujuan-tindakan" className="inline-flex min-h-[44px] items-center text-[var(--tint)]">Kembali ke daftar</Link>
    </>
  );
}

export default function PersetujuanTindakanVisitPage({ params }: { params: Promise<{ visitId: string }> }) {
  return (
    <main className="mx-auto grid w-full max-w-[900px] min-w-0 grid-cols-[minmax(0,1fr)] gap-5">
      <Suspense fallback={<LoadingList rows={4} />}>
        <Body params={params} />
      </Suspense>
    </main>
  );
}
